202	    let mut context_fields = Vec::new();
203	
204	    let _ = attr.parse_nested_meta(|nested_meta| {
205	        context_fields.push(nested_meta.path.get_ident().unwrap().clone());
206	        Ok(())
207	    });
208	
209	    if context_fields.len() != 1 {
210	        None
211	    } else {
212	        context_fields.pop()
213	    }
